// trimming. consumeSegment also processes the pending heap and must not report
// those internal replays as newly received duplicates.
// +checklocks:r.ep.mu
func (r *receiver) noteDuplicateSegment(start seqnum.Value, length seqnum.Size) {
	if !r.ep.SACKPermitted {
		r.ep.dsackPending = false
		return
	}
	if length == 0 {
		return
	}
	r.ep.dsackPending = false
	end := start.Add(length)
	if start.LessThan(r.RcvNxt) {
		if r.RcvNxt.LessThan(end) {
			end = r.RcvNxt
		}
		r.ep.dsackBlock = header.SACKBlock{Start: start, End: end}
		r.ep.dsackPending = start.LessThan(end)
		return
	}
	// A heap's backing slice is not in sequence order. Gather overlaps and
	// report the first contiguous duplicate subrange of this wire segment.
	// Only actual payload counts; a queued FIN consumes no duplicate data.
	var overlaps []header.SACKBlock
	for _, old := range r.pendingRcvdSegments {
		if old.payloadSize() == 0 {
			continue
		}
		oldStart, oldEnd := old.sequenceNumber, old.sequenceNumber.Add(seqnum.Size(old.payloadSize()))
		duplicate := header.SACKBlock{Start: start, End: end}
		if duplicate.Start.LessThan(oldStart) {
			duplicate.Start = oldStart
		}
		if oldEnd.LessThan(duplicate.End) {
			duplicate.End = oldEnd
		}
		if duplicate.Start.LessThan(duplicate.End) {
			overlaps = append(overlaps, duplicate)
		}
	}
	if len(overlaps) == 0 {
		return
	}
	sort.Slice(overlaps, func(i, j int) bool { return overlaps[i].Start.LessThan(overlaps[j].Start) })
	duplicate := overlaps[0]
	for _, next := range overlaps[1:] {
		if duplicate.End.LessThan(next.Start) {
			break
